from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = m
            extras = 0

            for i, p in enumerate(points):
                need = (target + p - 1) // p

                if i == n - 1:
                    if need > extras:
                        moves -= 2 * (need - extras) - 1
                elif need <= extras:
                    moves -= 1
                    extras = 0
                else:
                    add = need - extras
                    moves -= 2 * add - 1
                    extras = add - 1

                if moves < 0:
                    return False

            return True

        left, right = 0, min(points) * (m + 1)

        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1

